    d.innerHTML = '<div class="ml-dhead"><button type="button" class="ml-back" data-ml-back>' + ICON_BACK + 'MLW</button>' +
      '<p class="ml-kick">' + esc(kick) + '</p><h2 class="ml-dt">' + esc(title) + '</h2><p class="ml-sec__blurb">' + esc(sub) + "</p>" + yearNav + "</div>" +
      '<div class="ml-dbody">' + groupsHtml(groups, chip) + "</div>";
